using LittleLeo;
using Spine.Unity;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ReefRuinsButtonCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/ReefRuinsButtonCustomEventSetup", order = 0)]
public class ReefRuinsButtonCustomEventSetup : ButtonCustomEventSetup
{
	private const string reefRuinsButtonPressedEventDescriptionID = "ReefRuinsButtonPressedEventDescription";

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string vesselAnimationName;

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string vesselIdleAnimationName;

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string starShardsAnimationName;

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string starShardsIdleAnimationName;

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string crimsonVaultAnimationName;

	[SerializeField]
	[SpineAnimation("", "skeletonDataAsset", true, false)]
	private string crimsonVaultIdleAnimationName;

	public override string GetButtonPressedEventDescription(int buttonIndex)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ReefRuinsButtonPressedEventDescription");
	}

	public string GetBaseButtonPressedEventDescription(int buttonIndex)
	{
		return base.GetButtonPressedEventDescription(buttonIndex);
	}

	public void ChangeSkeletonAnimationVessel(EventButton eventButton)
	{
		ChangeSkeletonAnimation(eventButton, vesselAnimationName, vesselIdleAnimationName);
	}

	public void ChangeSkeletonAnimationStarShards(EventButton eventButton)
	{
		ChangeSkeletonAnimation(eventButton, starShardsAnimationName, starShardsIdleAnimationName);
	}

	public void ChangeSkeletonAnimationCrimsonVault(EventButton eventButton)
	{
		ChangeSkeletonAnimation(eventButton, crimsonVaultAnimationName, crimsonVaultIdleAnimationName);
	}

	private void ChangeSkeletonAnimation(EventButton eventButton, string skillAnimationNameExternal, string skillIdleAnimationNameExternal)
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(eventButton.EventsPanel.EventSpriteGameObject.GetComponent<EventSpritesSkeleton>().AfterStartingAnimationCoroutine(skillAnimationNameExternal, skillIdleAnimationNameExternal));
	}
}
